WITH valid AS (SELECT id, quantity, unit_price, LEAST(unit_price, quantity) AS least_unit_price_quantity FROM order_items WHERE unit_price <= 240), base AS (SELECT *, COALESCE(quantity, 0) AS quantity_filled, unit_price / NULLIF(least_unit_price_quantity, 0) AS unit_price_per_least_unit_price_quantity FROM valid WHERE quantity <= 6), valid_order_items AS (SELECT id, quantity, unit_price, least_unit_price_quantity, quantity_filled, unit_price_per_least_unit_price_quantity - unit_price AS unit_price_per_least_unit_price_quantity_minus_unit_price, ROUND(unit_price, 0) AS unit_price_rounded FROM base WHERE least_unit_price_quantity BETWEEN 28 AND 63), metrics AS (SELECT *, NTILE(5) OVER (ORDER BY unit_price_rounded DESC, id) AS unit_price_rounded_bucket, LAST_VALUE(unit_price) IGNORE NULLS OVER (ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_unit_price FROM valid_order_items) SELECT id, unit_price, least_unit_price_quantity, quantity_filled, unit_price_rounded, last_known_unit_price FROM metrics ORDER BY unit_price, unit_price_rounded DESC;
